const result1 = defu({}, payload1);
console.log("Test 1 - result1:", result1);
console.log("Test 1 - result1.__proto__:", result1.__proto__);
console.log("Test 1 - has own 'polluted' in result1:", 'polluted' in result1);
console.log("Test 1 - result1.polluted:", (result1 as any).polluted);

// Test 2: __proto__ in baseObject  
const payload2 = JSON.parse('{"__proto__": {"polluted": true}}');
const result2 = defu(payload2, {});
console.log("\nTest 2 - result2:", result2);
console.log("Test 2 - result2.__proto__:", result2.__proto__);
console.log("Test 2 - result2.polluted:", (result2 as any).polluted);

// Test 3: Two objects with __proto__
