import { defu } from "./src/defu.ts";

// Test: __proto__ as a key should be treated as a regular property
const payload = JSON.parse('{"__proto__": {"polluted": true}}');
const result = defu({}, payload);

console.log("result:", result);
console.log("result.__proto__:", result.__proto__);

// The result object should NOT have its prototype changed
console.log("Prototype is Object.prototype?", Object.getPrototypeOf(result) === Object.prototype);
console.log("Has 'polluted' in prototype chain?", 'polluted' in result);
console.log("result.polluted:", (result as any).polluted);

// After fix: result should be {} (skipping __proto__)
// Before fix: result had prototype = {polluted: true}
console.log("Is __proto__ own property of result?", Object.prototype.hasOwnProperty.call(result, "__proto__"));

// Verify Object.prototype is clean
console.log("\nObject.prototype.polluted:", (Object.prototype as any).polluted);
console.log("({}).polluted:", ({} as any).polluted);

// Test 2: defu with __proto__ in baseObject
const payload2 = JSON.parse('{"__proto__": {"polluted2": true}}');
const result2 = defu(payload2, {});
console.log("\nTest 2 - result2:", result2);
console.log("Test 2 - result2.polluted2:", (result2 as any).polluted2);
console.log("Test 2 - Object.prototype.polluted2:", (Object.prototype as any).polluted2);

// Test 3: Two objects with __proto__
const payload3 = JSON.parse('{"__proto__": {"polluted3": true}}');
const payload4 = JSON.parse('{"__proto__": {"polluted4": true}}');
const result3 = defu(payload3, payload4);
console.log("\nTest 3 - result3:", result3);
console.log("Test 3 - result3.polluted3:", (result3 as any).polluted3);
console.log("Test 3 - result3.polluted4:", (result3 as any).polluted4);

// Test 4: Nested __proto__
const payload5 = JSON.parse('{"a": {"__proto__": {"polluted5": true}}}');
const result4 = defu({}, payload5);
console.log("\nTest 4 - result4:", result4);
console.log("Test 4 - result4.a:", result4.a);
console.log("Test 4 - ({} as any).polluted5:", ({} as any).polluted5);

// Test 5: All should be clean
console.log("\n=== Final checks ===");
console.log("Object.prototype.polluted:", (Object.prototype as any).polluted);
console.log("Object.prototype.polluted2:", (Object.prototype as any).polluted2);
console.log("Object.prototype.polluted3:", (Object.prototype as any).polluted3);
console.log("Object.prototype.polluted4:", (Object.prototype as any).polluted4);
console.log("Object.prototype.polluted5:", (Object.prototype as any).polluted5);
console.log("({}).polluted:", ({} as any).polluted);
console.log("({}).polluted2:", ({} as any).polluted2);
console.log("({}).polluted3:", ({} as any).polluted3);
console.log("({}).polluted4:", ({} as any).polluted4);
console.log("({}).polluted5:", ({} as any).polluted5);

